"use client";
import { DotLottieReact } from "@lottiefiles/dotlottie-react";

/** Lottie vinyl (public/anim/vinyl.json, generated by scripts/make-lottie.ts). Falls back to CSS when the player cannot load. */
export function Vinyl({ size = 160, playing = true }: { size?: number; playing?: boolean }) {
  return (
    <div style={{ width: size, height: size }} className="relative" aria-hidden>
      <DotLottieReact src="/anim/vinyl.json" loop autoplay={playing} style={{ width: size, height: size }} />
    </div>
  );
}
